'use strict';

// A detached flight still settles its original callers. Only the registered
// flight may commit a value or remove itself from the registry.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key);
      const promise = Promise.resolve().then(work).then(value => {
        if (pending.get(key) === promise) {
          pending.delete(key);
          commit(value);
        }
        return value;
      }, reason => {
        if (pending.get(key) === promise) pending.delete(key);
        throw reason;
      });
      pending.set(key, promise);
      return promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };
